python3 << 'EOF'
import json
from pathlib import Path

# Load data
with open('/app/task_file/input_data/shipments.jsonl') as f:
    shipments = {json.loads(line)['shipment_id']: json.loads(line) for line in f}

with open('/app/task_file/input_data/warehouses.jsonl') as f:
    warehouses = {json.loads(line)['warehouse_id']: json.loads(line) for line in f}

with open('/app/task_file/input_data/routes.jsonl') as f:
    routes = {}
    routes_by_key = {}
    for line in f:
        r = json.loads(line)
        routes[r['route_id']] = r
        routes_by_key[(r['warehouse_id'], r['destination_id'])] = r

with open('/app/task_file/input_data/destinations.jsonl') as f:
    destinations = {json.loads(line)['destination_id']: json.loads(line) for line in f}

shipment = shipments[990]
print(f"Shipment 990: {shipment}")
print(f"\nDestination: {destinations[shipment['destination_id']]}")

print("\nLooking for valid routes:")
for (wh_id, dest_id), route in routes_by_key.items():
    if dest_id != shipment['destination_id']:
        continue
    wh = warehouses[wh_id]
    dest = destinations[dest_id]

    # Check capabilities
    if shipment['requires_hazmat'] and not wh['handles_hazmat']:
        continue
    if shipment['requires_refrigerated'] and not wh['handles_refrigerated']:
        continue
    if shipment['requires_oversized'] and not wh['handles_oversized']:
        continue

    # Check route capabilities
    if shipment['requires_hazmat'] and not route['allows_hazmat']:
        continue
    if shipment['requires_refrigerated'] and not route['allows_refrigerated']:
        continue
    if shipment['requires_oversized'] and not route['allows_oversized']:
        continue

    # Check capacities
    if shipment['volume'] > route['capacity_volume']:
        continue
    if shipment['weight'] > route['capacity_weight']:
        continue
    if shipment['volume'] > wh['volume_capacity']:
        continue
    if shipment['weight'] > wh['weight_capacity']:
        continue

    arrival = wh['availability_start'] + route['transit_time_hours']

    # Check deadline
    if arrival > shipment['deadline_hours']:
        print(f"  WH{wh_id} -> Dest{dest_id}: arrival={arrival:.2f}, deadline={shipment['deadline_hours']} - FAIL (late)")
        continue

    # Check time window
    if arrival < dest['delivery_window_start'] or arrival > dest['delivery_window_end']:
        print(f"  WH{wh_id} -> Dest{dest_id}: arrival={arrival:.2f}, window=[{dest['delivery_window_start']}, {dest['delivery_window_end']}] - FAIL (time window)")
        continue

    print(f"  WH{wh_id} -> Dest{dest_id}: arrival={arrival:.2f}, cost={(wh['base_handling_cost'] * shipment['volume']/100 + route['base_cost_per_km'] * route['distance_km'] * shipment['weight']/1000) * shipment['priority_multiplier']:.2f}")
EOF

